MOD = 998244353

def pow(a, b):
    if b == 0:
        return 1
    ret = pow((a ** 2) % MOD, b // 2)
    if b % 2:
        ret = ret * a % MOD
    return ret

def countValidConfigurations(N, P, S):
    def countL():
        cnt = 0
        spoon = [False] * N
        for p in P:
            if S[p] == "L":
                spoon[p] = True
            elif S[p] == "R":
                if not spoon[(p + 1) % N]:
                    return 0
                spoon[p] = True
            elif S[p] == "?":
                if spoon[(p + 1) % N]:
                    cnt += 1
                spoon[p] = True
        return pow(2, cnt)

    def countR():
        cnt = 0
        spoon = [False] * N
        for p in P:
            if S[p] == "R":
                spoon[(p + 1) % N] = True
            elif S[p] == "L":
                if not spoon[p]:
                    return 0
                spoon[(p + 1) % N] = True
            elif S[p] == "?":
                if spoon[p]:
                    cnt += 1
                spoon[(p + 1) % N] = True
        return pow(2, cnt)

    ans = 0
    if S[P[0]] == "L":
        ans = countL()
    elif S[P[0]] == "R":
        ans = countR()
    elif S[P[0]] == "?":
        ans = (countL() + countR()) % MOD

    return ans

